using UnityEngine;

namespace Deadzone.Core
{
    /// <summary>
    /// Camera-following rain (falling streaks + ground splashes) and occasional lightning flashes.
    /// Particles live in world space inside a box centred on what the camera is looking at, so the
    /// cost is fixed (~700 streaks + ~150 splashes) no matter how big the map is.
    /// Materials come from Resources/FX (generated by Deadzone.Editor.MoodBuilder).
    /// </summary>
    public class WeatherRain : MonoBehaviour
    {
        private const string StreakMatPath = "FX/M_RainStreak";
        private const string SplashMatPath = "FX/M_RainSplash";

        private bool rainOn, lightningOn;
        private float moonBase;
        private Transform rig;
        private ParticleSystem streaks, splashes;
        private Light moon;
        private float nextFlash, flashT = -1f;
        private Color ambientSkyBase;

        public void Configure(bool rain, bool lightning, float moonIntensity)
        {
            rainOn = rain; lightningOn = lightning; moonBase = moonIntensity;
        }

        private void Start()
        {
            moon = RenderSettings.sun;
            ambientSkyBase = RenderSettings.ambientSkyColor;
            nextFlash = Time.time + Random.Range(12f, 22f);
            if (!rainOn) return;

            var streakMat = Resources.Load<Material>(StreakMatPath);
            var splashMat = Resources.Load<Material>(SplashMatPath);
            if (streakMat == null || splashMat == null)
            {
                Debug.LogWarning("[WeatherRain] Rain materials missing from Resources/FX; run Deadzone/Art/Apply Night Rain Mood.");
                return;
            }
            rig = new GameObject("RainRig").transform;
            streaks = BuildStreaks(rig, streakMat);
            splashes = BuildSplashes(rig, splashMat);
            Follow(true);
        }

        private void LateUpdate()
        {
            if (rig != null) Follow(false);
            if (lightningOn) UpdateLightning();
        }

        /// <summary>Centre the rain box on the ground point under the middle of the screen.</summary>
        private void Follow(bool snap)
        {
            var cam = UnityEngine.Camera.main;
            if (cam == null) return;
            var ray = new Ray(cam.transform.position, cam.transform.forward);
            float t = Mathf.Abs(ray.direction.y) > 0.01f ? -ray.origin.y / ray.direction.y : 15f;
            Vector3 focus = ray.GetPoint(Mathf.Clamp(t, 0f, 60f));
            focus.y = 0f;
            rig.position = focus;
        }

        private static ParticleSystem BuildStreaks(Transform parent, Material mat)
        {
            var go = new GameObject("RainStreaks");
            go.transform.SetParent(parent, false);
            go.transform.localPosition = new Vector3(0f, 13f, 2f);
            // Emit along local +Z; tilt so rain falls mostly down with a little wind.
            go.transform.localRotation = Quaternion.Euler(82f, 12f, 0f);
            var ps = go.AddComponent<ParticleSystem>();
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);

            var main = ps.main;
            main.loop = true;
            main.duration = 1f;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.55f, 0.65f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(20f, 25f);
            main.startSize = new ParticleSystem.MinMaxCurve(0.025f, 0.045f);
            main.startColor = new Color(0.72f, 0.80f, 0.95f, 0.38f);
            main.maxParticles = 800;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.prewarm = true;

            var em = ps.emission;
            em.rateOverTime = 1100f;

            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Box;
            shape.scale = new Vector3(40f, 34f, 0.5f);

            var r = go.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Stretch;
            r.lengthScale = 1f;
            r.velocityScale = 0.035f;
            r.sharedMaterial = mat;
            r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            r.receiveShadows = false;
            ps.Play();
            return ps;
        }

        private static ParticleSystem BuildSplashes(Transform parent, Material mat)
        {
            var go = new GameObject("RainSplashes");
            go.transform.SetParent(parent, false);
            go.transform.localPosition = new Vector3(0f, 0.04f, 2f);
            go.transform.localRotation = Quaternion.Euler(-90f, 0f, 0f);
            var ps = go.AddComponent<ParticleSystem>();
            ps.Stop(true, ParticleSystemStopBehavior.StopEmittingAndClear);

            var main = ps.main;
            main.loop = true;
            main.duration = 1f;
            main.startLifetime = 0.28f;
            main.startSpeed = 0f;
            main.startSize = new ParticleSystem.MinMaxCurve(0.18f, 0.34f);
            main.startColor = new Color(0.75f, 0.83f, 0.95f, 0.45f);
            main.maxParticles = 200;
            main.simulationSpace = ParticleSystemSimulationSpace.World;

            var em = ps.emission;
            em.rateOverTime = 420f;

            var shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Box;
            shape.scale = new Vector3(30f, 24f, 0.01f);

            var size = ps.sizeOverLifetime;
            size.enabled = true;
            size.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 0.4f, 1f, 1.4f));

            var col = ps.colorOverLifetime;
            col.enabled = true;
            var g = new Gradient();
            g.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                      new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0f, 1f) });
            col.color = g;

            var r = go.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.HorizontalBillboard;
            r.sharedMaterial = mat;
            r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            r.receiveShadows = false;
            ps.Play();
            return ps;
        }

        /// <summary>Rare double-flash: moon + sky ambient spike for ~0.3 s.</summary>
        private void UpdateLightning()
        {
            if (moon == null) return;
            if (flashT < 0f)
            {
                if (Time.time < nextFlash) return;
                flashT = 0f;
            }
            flashT += Time.deltaTime;
            // two quick pulses: 0–0.07 s and 0.14–0.30 s
            float k = flashT < 0.07f ? 1f : flashT < 0.14f ? 0.15f : flashT < 0.30f ? Mathf.Lerp(0.8f, 0f, (flashT - 0.14f) / 0.16f) : 0f;
            moon.intensity = moonBase + k * 2.2f;
            RenderSettings.ambientSkyColor = ambientSkyBase + new Color(0.35f, 0.4f, 0.5f) * k;
            if (flashT >= 0.30f)
            {
                moon.intensity = moonBase;
                RenderSettings.ambientSkyColor = ambientSkyBase;
                flashT = -1f;
                nextFlash = Time.time + Random.Range(18f, 40f);
            }
        }

        private void OnDestroy()
        {
            if (rig != null) Destroy(rig.gameObject);
        }
    }
}
